{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 조례상 공원에서 강아지 똥을 안 치우고 가는 사람에 대한 처벌(과태료) 여부 및 기준",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "서울특별시 동물보호 조례 제7조제3항제3호에 따르면 등록대상동물의 소유자등은 배설물이 생겼을 때 즉시 수거하여야 하므로, 공원에서 강아지 똥을 치우지 않고 가는 행위는 이 준수사항을 위반한 것이다. 다만 해당 조문에는 위반 시 처벌(과태료) 규정이 직접 명시되어 있지 않다. 서울특별시 도시공원 조례 제23조제1항은 시장이 법 제56조에 따라 과태료를 부과하는 기준이 영 제51조제1항 별표 4와 같다고 정하고 있으므로, 실제 과태료 부과 여부와 금액은 그 별표 기준에 따른다. 따라서 신고 시 어떤 처벌을 받는지는 도시공원 조례 제23조제1항이 가리키는 별표 4의 기준에 따라 결정되며, 제공된 원문만으로는 구체적인 과태료 금액을 확정할 수 없다.",
          "b_ids": "동물보호:제7조제3항제3호, 도시공원:제23조제1항"
        }
      ],
      "e_status": "CORE_MISSING"
    }
  ]
}
